mapper.select:
SELECT FAQ_ID, CATEGORY, QUESTION, KEYWORDS, ANSWER, CREATED_BY, CREATED_AT
  FROM FAQ
 WHERE FAQ_ID = #{faqId}

mapper.update:
UPDATE FAQ
   SET CATEGORY  = #{category},
       QUESTION  = #{question},
       KEYWORDS  = #{keywords},
       ANSWER    = #{answer}
 WHERE FAQ_ID = #{faqId}
